1	import { writeFileSync } from 'node:fs';
2	import { join } from 'node:path';
3	import { page } from '../../lib/html.mjs';
4	import { defineTask, str, norm, serverEvents, result } from '../common.mjs';
5	
6	const uploadPath = (c, env) => join(env.workdir, `bench-upload-${c.runId}.txt`);
7	
8	const upload = defineTask({
9	  id: 'k1-upload',
10	  tier: 'k1',
11	  capability: 'file upload',
12	  title: 'File upload',
13	  answer: { receipt: str('the receipt code shown after uploading') },
14	  prepare: (c, env) => writeFileSync(uploadPath(c, env), `Expense report\nupload-token: ${c.code('u')}\n`),
15	  prompt: (c, env) =>
16	    `Upload the file at ${uploadPath(c, env)} using the upload form, then report the receipt code shown after the upload.`,
17	  routes: {
18	    'GET /': () =>
19	      page({
20	        title: 'Expenses',
21	        body: `<div class="card"><h1>Submit an expense report</h1>
22	          <form method="post" action="upload" enctype="multipart/form-data">
23	            <label for="file">Report file</label><input id="file" type="file" name="file">
24	            <div style="margin-top:12px"><button type="submit">Upload</button></div>
25	          </form></div>`,
26	      }),
27	    'POST /upload': (c, req) => {
28	      const text = req.body.toString('latin1');
29	      const token = text.match(/upload-token: ([A-Z0-9]+)/)?.[1] ?? null;
30	      c.log('upload', { token, bytes: req.body.length });
31	      const ok = token === c.code('u');
32	      return page({
33	        title: 'Upload result',
34	        body: ok
35	          ? `<div class="card result"><h1>Report received</h1><p>Receipt: <strong>${c.code('r')}</strong></p></div>`
36	          : '<div class="card"><h1>File not recognised</h1><a href="./">Try again</a></div>',
37	      });
38	    },
39	  },
40	  check: (c, out, events) => {
