1	#!/usr/bin/env node
2	// Runs benchmark tasks against browser variants, one run at a time, and appends one JSON
3	// record per run to <out>/runs.jsonl. Re-running the same command resumes: finished runs
4	// are skipped, rate-limited runs are retried.
5	//
6	//   node src/runner.mjs --tasks k0,k1 --variants all --repeats k0=3,k1=3 --out results/main
7	import { spawn } from 'node:child_process';
8	import { appendFileSync, existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
9	import { join } from 'node:path';
10	import { parseArgs } from 'node:util';
11	import { startServer, makeContext, runEvents } from './server.mjs';
12	import { TASKS, selectTasks } from './tasks/index.mjs';
13	import { buildPrompt } from './tasks/common.mjs';
14	import { VARIANTS, ROOT, WORKDIR, ORCA_WORKTREE, selectVariants, claudeArgs } from './variants.mjs';
15	import { parseStream, isRateLimited, isApiError } from './metrics.mjs';
16	import { chromeWindowBounds, chromeWindowIds, cleanupRun, safariAutomationPids, trackDescendantBrowsers } from './cleanup.mjs';
17	import { newRunId, rng, shuffle } from './lib/codes.mjs';
18	
19	const { values: options } = parseArgs({
20	  options: {
21	    tasks: { type: 'string', default: 'k0' },
22	    variants: { type: 'string', default: 'all' },
23	    repeats: { type: 'string', default: '1' },
24	    out: { type: 'string', default: 'results/main' },
25	    seed: { type: 'string', default: 'bench-2026' },
26	    model: { type: 'string', default: 'claude-opus-5-5' },
27	    effort: { type: 'string', default: 'medium' },
28	    'max-weekly': { type: 'string', default: '0.85' },
29	    'max-five-hour': { type: 'string', default: '0.8' },
30	    'max-minutes': { type: 'string', default: '100000' },
31	    'max-runs': { type: 'string', default: '100000' },
32	    'dry-run': { type: 'boolean', default: false },
33	  },
34	});
35	
36	const outDir = join(ROOT, options.out);
37	const runsFile = join(outDir, 'runs.jsonl');
38	mkdirSync(join(outDir, 'raw'), { recursive: true });
39	mkdirSync(WORKDIR, { recursive: true });
40	
41	function repeatsFor(tier) {
42	  const spec = options.repeats;
43	  if (/^\d+$/.test(spec)) return Number(spec);
44	  const map = Object.fromEntries(spec.split(',').map((p) => p.split('=')));
45	  return Number(map[tier] ?? 1);
46	}
47	
48	// Blocks: every repeat walks all tasks in a shuffled order and runs every variant of a
49	// task back to back in a shuffled order, so time-of-day and API latency drift spread
50	// evenly over variants.
51	function buildPlan(tasks, variants) {
52	  const plan = [];
53	  const maxRepeats = Math.max(...tasks.map((t) => repeatsFor(t.tier)));
54	  for (let rep = 1; rep <= maxRepeats; rep++) {
55	    const taskOrder = shuffle(rng(options.seed, `tasks:${rep}`), tasks.filter((t) => repeatsFor(t.tier) >= rep));
56	    for (const task of taskOrder) {
57	      for (const variant of shuffle(rng(options.seed, `variants:${rep}:${task.id}`), variants)) {
58	        plan.push({ taskId: task.id, variant, rep, key: `${task.id}|${variant}|${rep}` });
59	      }
60	    }
61	  }
62	  return plan;
63	}
64	
65	const DONE_STATUSES = ['ok', 'timeout', 'error'];
66	const MIN_START_WIDTH = 1700;
67	
68	function finishedKeys() {
69	  if (!existsSync(runsFile)) return new Set();
70	  const keys = new Set();
71	  for (const line of readFileSync(runsFile, 'utf8').split('\n')) {
72	    if (!line.trim()) continue;
73	    const record = JSON.parse(line);
74	    if (DONE_STATUSES.includes(record.status)) keys.add(record.key);
75	  }
76	  return keys;
77	}
78	
79	const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
80	
81	function runClaude(args, runDir, timeoutSec, tracked) {
82	  return new Promise((resolve) => {
83	    const lines = [];
84	    const arrivals = [];
85	    let stderr = '';
86	    let buffer = '';
87	    let timedOut = false;
88	    const started = Date.now();
89	    const child = spawn('claude', args, { cwd: WORKDIR, stdio: ['ignore', 'pipe', 'pipe'], detached: true });
90	    child.stdout.on('data', (chunk) => {
91	      buffer += chunk;
92	      let index;
93	      while ((index = buffer.indexOf('\n')) >= 0) {
94	        lines.push(buffer.slice(0, index));
95	        arrivals.push(Date.now());
96	        buffer = buffer.slice(index + 1);
97	      }
98	    });
99	    child.stderr.on('data', (chunk) => (stderr += chunk));
100	    const poller = setInterval(() => trackDescendantBrowsers(child.pid, tracked), 1500);
101	    const killGroup = (signal) => {
102	      try {
103	        process.kill(-child.pid, signal);
104	      } catch {}
105	    };
106	    const timer = setTimeout(() => {
107	      timedOut = true;
108	      killGroup('SIGTERM');
109	      setTimeout(() => killGroup('SIGKILL'), 5000);
110	    }, timeoutSec * 1000);
111	    child.on('close', (exitCode) => {
112	      clearTimeout(timer);
113	      clearInterval(poller);
114	      if (buffer.trim()) {
115	        lines.push(buffer);
116	        arrivals.push(Date.now());
117	      }
118	      writeFileSync(join(runDir, 'stream.jsonl'), lines.join('\n') + '\n');
119	      writeFileSync(join(runDir, 'arrivals.json'), JSON.stringify(arrivals.map((t) => t - started)));
120	      writeFileSync(join(runDir, 'stderr.txt'), stderr);
121	      resolve({ lines, arrivals, stderr, exitCode, timedOut, wallMs: Date.now() - started });
122	    });
123	  });
124	}
125	
126	function viewportSummary(events) {
127	  const views = events.filter((e) => e.source === 'client' && ['pageview', 'resize'].includes(e.type) && e.data?.top !== false);
128	  if (views.length === 0) return null;
129	  const last = views.at(-1).data;
130	  return { w: last.w, h: last.h, dpr: last.dpr, first: { w: views[0].data.w, h: views[0].data.h }, samples: views.length };
131	}
132	
