24	export function rng(runId, key) {
25	  const digest = createHmac('sha256', SECRET).update(`${runId}:rng:${key}`).digest();
26	  let state = digest.readUInt32LE(0) || 1;
27	  return () => {
28	    state ^= state << 13;
29	    state ^= state >>> 17;
30	    state ^= state << 5;
31	    return (state >>> 0) / 4294967296;
32	  };
33	}
