40	  const copy = [...list];
41	  for (let i = copy.length - 1; i > 0; i--) {
42	    const j = Math.floor(random() * (i + 1));
43	    [copy[i], copy[j]] = [copy[j], copy[i]];
44	  }
45	  return copy;
46	}
