1	import { page, escapeHtml } from '../../lib/html.mjs';
2	import { defineTask, str, num, norm, result } from '../common.mjs';
3	import { shuffle } from '../../lib/codes.mjs';
4	
5	const CATEGORIES = ['Tents', 'Backpacks', 'Sleeping Bags', 'Stoves'];
6	const ADJECTIVES = ['Summit', 'Ridge', 'Alpine', 'Canyon', 'Glacier', 'Timber', 'Harbor', 'Mesa', 'Aurora', 'Cascade', 'Juniper', 'Basalt'];
7	
8	// 48 products with distinct prices. The target (cheapest in-stock tent rated 4.0+) always
9	// has two cheaper decoys: an in-stock tent rated 3.9 and a 4.6-rated tent out of stock.
10	function catalog(c) {
11	  const cached = c.state.catalog;
12	  if (cached) return cached;
13	  const random = c.rng('catalog');
14	  const prices = shuffle(random, Array.from({ length: 48 }, (_, i) => 4900 + i * 1037 + Math.floor(random() * 900)));
15	  const names = shuffle(random, ADJECTIVES);
16	  const products = [];
17	  for (let i = 0; i < 48; i++) {
18	    const category = CATEGORIES[i % 4];
19	    const rating = Math.round((2.5 + random() * 2.5) * 10) / 10;
20	    products.push({
21	      sku: `${category.slice(0, 2).toUpperCase()}-${c.code(`sku${i}`, 5)}`,
22	      name: `${names[i % names.length]} ${category === 'Sleeping Bags' ? 'Sleeping Bag' : category.slice(0, -1)} ${100 + i}`,
23	      category,
24	      priceCents: prices[i],
25	      rating,
26	      inStock: random() > 0.3,
27	    });
28	  }
29	  const tents = products.filter((p) => p.category === 'Tents').sort((a, b) => a.priceCents - b.priceCents);
30	  const [decoyLowRating, decoyOutOfStock, target] = tents;
31	  decoyLowRating.rating = 3.9;
32	  decoyLowRating.inStock = true;
33	  decoyOutOfStock.rating = 4.6;
34	  decoyOutOfStock.inStock = false;
35	  target.rating = 4.2;
36	  target.inStock = true;
37	  c.state.catalog = { products, target };
38	  return c.state.catalog;
39	}
40	
41	const catalogTask = defineTask({
42	  id: 'k2-catalog',
43	  tier: 'k2',
44	  capability: 'SPA filters + async results',
45	  title: 'Filter a product catalog',
46	  answer: { sku: str('the SKU of the product'), price: num('its price in dollars') },
47	  prompt: () =>
48	    'Using the product catalog, find the cheapest in-stock product in the Tents category with a rating of at least 4.0 stars. Report its SKU and price.',
49	  routes: {
50	    'GET /': () =>
51	      page({
52	        title: 'Shop',
53	        css: `.filters{display:flex;gap:16px;flex-wrap:wrap;align-items:end}.filters label{margin:0}
54	          .grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-top:16px}.p{background:#fff;border:1px solid #dde1ea;border-radius:8px;padding:12px}
55	          .badge{font-size:12px;padding:2px 6px;border-radius:4px}.in{background:#dcf5e3}.out{background:#fde2e1}.loading{opacity:.4}`,
56	        body: `<h1>Gear catalog</h1><div class="card filters">
57	            <div><label for="cat">Category</label><select id="cat"><option value="">All</option>${CATEGORIES.map((x) => `<option>${x}</option>`).join('')}</select></div>
58	            <div><label for="rating">Minimum rating</label><select id="rating"><option value="0">Any</option><option value="3">3+</option><option value="4">4+</option><option value="4.5">4.5+</option></select></div>
59	            <div><label><input type="checkbox" id="stock"> In stock only</label></div>
60	            <div><label for="sort">Sort</label><select id="sort"><option value="featured">Featured</option><option value="price-asc">Price: low to high</option><option value="price-desc">Price: high to low</option></select></div>
61	            <button id="apply">Apply filters</button></div>
62	          <div id="grid" class="grid"></div><div id="pager" style="margin-top:12px;display:flex;gap:6px"></div>`,
63	        script: `let page = 1;
64	          async function load() {
65	            const grid = document.getElementById('grid');
66	            grid.classList.add('loading');
67	            const q = new URLSearchParams({ category: cat.value, minRating: rating.value, inStock: stock.checked ? '1' : '', sort: sort.value, page });
68	            const data = await (await fetch('api/products?' + q)).json();
69	            await new Promise((r) => setTimeout(r, 700));
70	            grid.classList.remove('loading');
71	            grid.innerHTML = data.items.map((p) => '<div class="p"><strong>' + p.name + '</strong><div class="muted">SKU ' + p.sku + '</div><div>$' + (p.priceCents / 100).toFixed(2) + ' · ★ ' + p.rating.toFixed(1) + '</div><span class="badge ' + (p.inStock ? 'in">In stock' : 'out">Out of stock') + '</span></div>').join('') || '<p>No products match.</p>';
72	            const pager = document.getElementById('pager');
73	            pager.innerHTML = '';
74	            for (let i = 1; i <= data.pages; i++) {
75	              const b = document.createElement('button');
76	              b.textContent = i; b.className = i === page ? '' : 'secondary';
77	              b.onclick = () => { page = i; load(); };
78	              pager.appendChild(b);
79	            }
80	          }
81	          document.getElementById('apply').onclick = () => { page = 1; load(); };
82	          load();`,
83	      }),
84	    'GET /api/products': (c, req) => {
85	      const { products } = catalog(c);
86	      const category = req.query.get('category');
87	      const minRating = Number(req.query.get('minRating') || 0);
88	      const inStock = req.query.get('inStock') === '1';
89	      const sort = req.query.get('sort');
90	      let items = products.filter((p) => (!category || p.category === category) && p.rating >= minRating && (!inStock || p.inStock));
91	      if (sort === 'price-asc') items = [...items].sort((a, b) => a.priceCents - b.priceCents);
92	      if (sort === 'price-desc') items = [...items].sort((a, b) => b.priceCents - a.priceCents);
93	      const pageNumber = Math.max(1, Number(req.query.get('page') || 1));
94	      c.log('products', { category, minRating, inStock, sort, page: pageNumber });
95	      return { json: { items: items.slice((pageNumber - 1) * 12, pageNumber * 12), pages: Math.max(1, Math.ceil(items.length / 12)) } };
96	    },
97	  },
98	  check: (c, out) => {
99	    const { target } = catalog(c);
100	    const pass = norm(out?.sku) === target.sku && Math.abs(Number(out?.price) - target.priceCents / 100) < 0.01;
101	    return result(pass, { expected: { sku: target.sku, price: target.priceCents / 100 }, got: out });
102	  },
103	});
