105	const CUSTOMERS = ['Northwind', 'Contoso', 'Fabrikam', 'Tailspin', 'Wingtip'];
106	const STATUSES = ['paid', 'overdue', 'pending'];
107	
108	function invoices(c) {
109	  if (c.state.invoices) return c.state.invoices;
110	  const random = c.rng('invoices');
111	  const rows = Array.from({ length: 95 }, (_, i) => ({
112	    number: `INV-${String(4100 + i)}`,
113	    customer: CUSTOMERS[Math.floor(random() * CUSTOMERS.length)],
114	    amountCents: 5000 + Math.floor(random() * 495000),
115	    status: STATUSES[Math.floor(random() * STATUSES.length)],
116	    due: `2026-${String(1 + Math.floor(random() * 9)).padStart(2, '0')}-${String(1 + Math.floor(random() * 28)).padStart(2, '0')}`,
117	  }));
118	  // Guarantee enough matching rows spread over several pages.
119	  for (const index of [3, 21, 38, 57, 74, 90]) Object.assign(rows[index], { customer: 'Northwind', status: 'overdue' });
120	  c.state.invoices = rows;
121	  return rows;
122	}
