124	const table = defineTask({
125	  id: 'k2-table',
126	  tier: 'k2',
127	  capability: 'paginated table aggregation',
128	  title: 'Aggregate a paginated table',
129	  answer: { total: num('the sum of the matching amounts in dollars'), count: num('how many invoices matched') },
130	  prompt: () =>
131	    'The invoice list is split over several pages. Add up the amounts of all invoices for customer "Northwind" whose status is "overdue". Report the total amount and how many invoices matched.',
