120	    },
121	  },
122	  check: (c, out, events) => {
123	    const p = customer(c);
124	    const order = serverEvents(events, 'order').at(-1)?.data || {};
125	    const fields = {
126	      name: (order.fullName || '').trim().toLowerCase() === p.name.toLowerCase(),
127	      email: (order.email || '').trim().toLowerCase() === p.email,
128	      phone: (order.phone || '').replace(/\D/g, '') === p.phoneDigits,
129	      street: (order.street || '').trim().toLowerCase() === p.street.toLowerCase(),
130	      city: (order.city || '').trim().toLowerCase() === p.city.toLowerCase(),
131	      state: order.state === p.state,
132	      zip: order.zip === p.zip,
133	      shipping: order.shipping === 'express',
134	      payment: order.payment === 'invoice',
135	      terms: order.terms === true,
136	    };
137	    const answer = norm(out?.orderNumber) === `AO-${c.digits('order', 6)}` && Math.abs(Number(out?.total) - TOTAL) < 0.01;
138	    return result(Object.values(fields).every(Boolean) && answer, { fields, answer, got: out });
139	  },
140	});
141	
142	const WIZARD_MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
143	
144	function wizardProfile(c) {
145	  const random = c.rng('wizard');
146	  return {
147	    year: String(2012 + Math.floor(random() * 12)),
148	    birthYear: 1968 + Math.floor(random() * 30),
149	    birthMonth: Math.floor(random() * 12),
