154	
155	const iso = (year, month, day) => `${year}-${String(month + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
156	
157	const wizard = defineTask({
158	  id: 'k2-wizard',
159	  tier: 'k2',
160	  capability: 'multi-step wizard + custom date picker',
161	  title: 'Quote wizard',
162	  answer: { reference: str('the quote reference') },
163	  prompt: (c) => {
