166	Vehicle type: Motorcycle, model year ${p.year}
167	Driver: Jordan Reyes, date of birth ${p.birthDay} ${WIZARD_MONTHS[p.birthMonth]} ${p.birthYear}
168	Always wears a helmet: Yes
169	Riding experience: ${p.experience} years
170	Go through every step, submit the request, and report the quote reference.`;
171	  },
172	  routes: {
173	    'GET /': () =>
174	      page({
175	        title: 'Get a Quote',
176	        css: `.steps{display:flex;gap:8px;margin-bottom:16px}.steps span{padding:4px 10px;border-radius:12px;background:#e3e6ee}.steps span.on{background:#243b6b;color:#fff}
177	          .step{display:none}.step.on{display:block}.err{color:#b42318;min-height:20px}
178	          .picker{position:relative;display:inline-block}.cal{position:absolute;top:110%;left:0;background:#fff;border:1px solid #99a;border-radius:8px;padding:10px;z-index:10;width:300px;box-shadow:0 6px 20px #0002}
179	          .cal .head{display:flex;justify-content:space-between;align-items:center;gap:6px}.cal .days{display:grid;grid-template-columns:repeat(7,1fr);gap:2px;margin-top:8px}
180	          .cal .days button{padding:4px 0;background:#f2f4f8;color:#1d2330;border:1px solid #dde}.cal .days button:hover{background:#dbe4ff}`,
181	        body: `<div class="card"><h1>Get a quote</h1>
182	          <div class="steps"><span data-s="1" class="on">1 Vehicle</span><span data-s="2">2 Driver</span><span data-s="3">3 Details</span><span data-s="4">4 Review</span></div>
183	          <section class="step on" data-step="1"><h2>Your vehicle</h2>
184	            <label><input type="radio" name="vehicle" value="car"> Car</label>
185	            <label><input type="radio" name="vehicle" value="motorcycle"> Motorcycle</label>
186	            <label><input type="radio" name="vehicle" value="rv"> RV</label>
187	            <label for="year">Model year</label><select id="year"><option value="">Select…</option>${Array.from({ length: 27 }, (_, i) => `<option>${2026 - i}</option>`).join('')}</select></section>
188	          <section class="step" data-step="2"><h2>Driver</h2>
189	            <label for="first">First name</label><input id="first"><label for="last">Last name</label><input id="last">
190	            <label for="dob">Date of birth</label><div class="picker"><input id="dob" readonly placeholder="Pick a date" style="cursor:pointer"><div class="cal" id="cal" hidden></div></div></section>
191	          <section class="step" data-step="3"><h2>Details</h2><div id="details"></div></section>
192	          <section class="step" data-step="4"><h2>Review</h2><div id="review"></div></section>
193	          <p class="err" id="err"></p>
194	          <button class="secondary" id="back" hidden>Back</button> <button id="next">Next</button> <button id="submit" hidden>Submit quote request</button>
195	          <div id="done" class="result" hidden></div></div>`,
196	        script: `const MONTHS = ${JSON.stringify(WIZARD_MONTHS)};
197	          const state = { step: 1, dob: null };
198	          const $ = (id) => document.getElementById(id);
199	          function show() {
200	            document.querySelectorAll('.step').forEach((s) => s.classList.toggle('on', Number(s.dataset.step) === state.step));
201	            document.querySelectorAll('.steps span').forEach((s) => s.classList.toggle('on', Number(s.dataset.s) === state.step));
202	            $('back').hidden = state.step === 1; $('next').hidden = state.step === 4; $('submit').hidden = state.step !== 4; $('err').textContent = '';
203	          }
204	          function vehicle() { return (document.querySelector('input[name=vehicle]:checked') || {}).value; }
205	          function renderDetails() {
206	            $('details').innerHTML = vehicle() === 'motorcycle'
207	              ? '<p>Do you always wear a helmet?</p><label><input type="radio" name="helmet" value="yes"> Yes</label><label><input type="radio" name="helmet" value="no"> No</label><label for="exp">Riding experience (years)</label><input id="exp" type="number" min="0" max="60">'
208	              : '<label for="miles">Annual mileage</label><select id="miles"><option value="">Select…</option><option>Under 5,000</option><option>5,000-10,000</option><option>Over 10,000</option></select>';
209	          }
210	          function values() {
211	            return { vehicle: vehicle(), year: $('year').value, first: $('first').value.trim(), last: $('last').value.trim(), dob: state.dob,
212	              helmet: (document.querySelector('input[name=helmet]:checked') || {}).value, experience: $('exp') ? $('exp').value : null, miles: $('miles') ? $('miles').value : null };
213	          }
214	          function validate() {
215	            const v = values();
216	            if (state.step === 1 && (!v.vehicle || !v.year)) return 'Choose a vehicle type and model year.';
217	            if (state.step === 2 && (!v.first || !v.last || !v.dob)) return 'Enter the driver name and date of birth.';
218	            if (state.step === 3 && v.vehicle === 'motorcycle' && (!v.helmet || v.experience === '')) return 'Answer both questions.';
219	            if (state.step === 3 && v.vehicle !== 'motorcycle' && !v.miles) return 'Choose the annual mileage.';
220	            return '';
221	          }
222	          $('next').onclick = () => {
223	            const error = validate();
224	            if (error) { $('err').textContent = error; return; }
225	            if (state.step === 1) renderDetails();
226	            state.step += 1;
227	            if (state.step === 4) { const v = values(); $('review').innerHTML = '<pre>' + JSON.stringify(v, null, 2) + '</pre>'; }
228	            show();
229	          };
230	          $('back').onclick = () => { state.step -= 1; show(); };
231	          $('submit').onclick = async () => {
232	            const data = await (await fetch('quote', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(values()) })).json();
233	            $('done').hidden = false; $('done').textContent = 'Quote requested. Reference: ' + data.reference;
234	          };
235	          let view = { y: 2000, m: 0 };
236	          function renderCal() {
237	            const cal = $('cal');
238	            const years = Array.from({ length: 90 }, (_, i) => 2026 - i).map((y) => '<option' + (y === view.y ? ' selected' : '') + '>' + y + '</option>').join('');
239	            const first = new Date(view.y, view.m, 1).getDay();
240	            const count = new Date(view.y, view.m + 1, 0).getDate();
241	            let days = '';
242	            for (let i = 0; i < first; i++) days += '<span></span>';
243	            for (let d = 1; d <= count; d++) days += '<button type="button" data-d="' + d + '">' + d + '</button>';
244	            cal.innerHTML = '<div class="head"><button type="button" id="prev">‹</button><strong>' + MONTHS[view.m] + '</strong><select id="cy">' + years + '</select><button type="button" id="nextm">›</button></div><div class="days">' + days + '</div>';
245	            $('prev').onclick = () => { view.m -= 1; if (view.m < 0) { view.m = 11; view.y -= 1; } renderCal(); };
246	            $('nextm').onclick = () => { view.m += 1; if (view.m > 11) { view.m = 0; view.y += 1; } renderCal(); };
247	            $('cy').onchange = (e) => { view.y = Number(e.target.value); renderCal(); };
248	            cal.querySelectorAll('[data-d]').forEach((b) => (b.onclick = () => {
249	              const d = Number(b.dataset.d);
250	              state.dob = view.y + '-' + String(view.m + 1).padStart(2, '0') + '-' + String(d).padStart(2, '0');
251	              $('dob').value = d + ' ' + MONTHS[view.m] + ' ' + view.y;
252	              cal.hidden = true;
253	            }));
254	          }
255	          $('dob').onclick = () => { const cal = $('cal'); cal.hidden = !cal.hidden; if (!cal.hidden) renderCal(); };`,
256	      }),
257	    'POST /quote': (c, req) => {
258	      const body = req.json();
259	      c.log('quote', body);
260	      return { json: { reference: `Q-${c.code('q')}` } };
261	    },
262	  },
263	  check: (c, out, events) => {
264	    const p = wizardProfile(c);
265	    const quote = serverEvents(events, 'quote').at(-1)?.data || {};
266	    const fields = {
267	      vehicle: quote.vehicle === 'motorcycle',
268	      year: quote.year === p.year,
269	      name: (quote.first || '').toLowerCase() === 'jordan' && (quote.last || '').toLowerCase() === 'reyes',
270	      dob: quote.dob === iso(p.birthYear, p.birthMonth, p.birthDay),
271	      helmet: quote.helmet === 'yes',
272	      experience: String(quote.experience) === p.experience,
273	    };
274	    const answer = norm(out?.reference) === `Q-${c.code('q')}`;
275	    return result(Object.values(fields).every(Boolean) && answer, { fields, answer, got: out?.reference, submitted: quote });
276	  },
277	});
