302	          <label for="u">Username</label><input id="u" name="username" autocomplete="off">
303	          <label for="p">Password</label><input id="p" name="password" type="password" autocomplete="off">
304	          <div style="margin-top:12px"><button type="submit">Sign in</button></div></form>`,
