307	      const { username, password: given } = req.form();
308	      const ok = username === USERNAME && given === password(c);
309	      c.log('login', { ok });
310	      if (!ok) return page({ title: 'Sign in', body: '<div class="card"><h1>Wrong username or password</h1><a href="./">Try again</a></div>' });
311	      return { redirect: 'verify', headers: { 'set-cookie': `bench_auth=${c.code('half', 12)}; Path=/; HttpOnly` } };
