324	      stage(c, req) === 'none'
325	        ? page({ title: 'Inbox', body: '<div class="card"><h1>Sign in first</h1></div>' })
326	        : page({
327	            title: 'Inbox',
328	            body: `<div class="card"><h1>Inbox</h1><table><tr><th>Received</th><th>Subject</th><th>Message</th></tr>
329	              <tr><td>Just now</td><td>Your sign-in code</td><td>Your verification code is <strong>${c.digits('otp')}</strong>. It expires in 10 minutes.</td></tr>
330	              <tr><td>2 hours ago</td><td>Your sign-in code</td><td>Your verification code is <strong>${c.digits('old1')}</strong>. It expires in 10 minutes.</td></tr>
331	              <tr><td>Yesterday</td><td>Your sign-in code</td><td>Your verification code is <strong>${c.digits('old2')}</strong>. It expires in 10 minutes.</td></tr>
332	              </table></div>`,
333	          }),
