357	          <label><input type="checkbox" name="sms" ${saved.sms ? 'checked' : ''}> SMS notifications</label>
358	          <button type="submit" style="margin-top:12px">Save</button>${c.state.savedOnce ? '<p class="result">Settings saved.</p>' : ''}</form>`,
